pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address depositor, uint256 amount) public {
        // keep inputs admissible and wide
        vm.assume(depositor != address(c) && depositor != address(this));
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the depositor and deposit `amount` into C via the payable receive()
        vm.deal(depositor, amount);
        vm.prank(depositor);
        (bool okDep,) = address(c).call{value: amount}("");
        assertTrue(okDep);

        // owner (deployer == this test contract) withdraws everything
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // GENERAL RULE: after any admissible deposit, withdrawAll drains the
        // contract's whole balance to 0 (the mutant always withdraws 0).
        assertTrue(ok && address(c).balance == 0);
    }
}

