pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // keep the domain wide: any actor that is not the contract itself and not
        // this test contract (which is c's owner via setUp deployment)
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        amount = bound(amount, 0, type(uint256).max / 2);

        // fund the contract so a successful drain is observable (also covers amount == 0)
        vm.deal(address(c), amount);

        uint256 cBalBefore = address(c).balance;
        uint256 actorBalBefore = actor.balance;

        // a NON-OWNER attempts to drain the contract
        bool ok;
        vm.prank(actor);
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // General rule: a withdrawAll by anyone but the owner reverts and moves no
        // funds anywhere — contract balance unchanged and caller gains nothing.
        assertTrue(
            !ok && address(c).balance == cBalBefore && actor.balance == actorBalBefore,
            "non-owner withdrawAll must be a no-op revert"
        );
    }
}

