pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // Keep the domain wide: any amount the contract can be funded with.
        vm.assume(amount < type(uint256).max / 2);

        // Fund the contract with exactly `amount` so a withdrawal of `amount` succeeds.
        vm.deal(address(c), amount);

        address owner = c.owner();
        // Caller must be the owner (onlyOwner). Zero out the caller's balance so the
        // delta is exactly the withdrawn amount.
        vm.deal(owner, 0);

        vm.prank(owner);
        c.withdraw(amount);

        // General rule: after the owner withdraws amount v, the CALLER (owner here)
        // holds exactly v more and the contract holds exactly v less.
        assertTrue(owner.balance == amount && address(c).balance == 0);
    }
}

