pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, address(c).balance > 0 ? address(c).balance : 0);
        // fund the contract (owner deposit) so a withdrawal is admissible
        vm.deal(address(this), amount);
        if (amount > 0) {
            (bool okDep, ) = address(c).call{value: amount}("");
            assertTrue(okDep);
        }
        vm.deal(actor, 1 wei);
        uint256 callerBefore = actor.balance;
        uint256 contractBefore = address(c).balance;

        vm.prank(actor);
        bool ok;
        if (actor == c.owner()) {
            // owner may withdraw; for the reference the CALLER (== owner here) is credited
            try c.withdraw(amount) { ok = true; } catch { ok = false; }
            assertTrue(
                (!ok && (contractBefore > amount)) ||
                (ok && actor.balance == callerBefore + amount && address(c).balance == contractBefore - amount),
                "withdraw must credit the calling address"
            );
        } else {
            try c.withdraw(amount) { ok = true; } catch { ok = false; }
            assertTrue(
                !ok || (actor.balance == callerBefore + amount && address(c).balance == contractBefore - amount),
                "any successful withdraw must credit the caller, never a third party"
            );
        }
    }
}

